struct BaseA {
    BaseA(int i) {}
};

struct BaseB {
    BaseB(double d) {}
};

struct Derived : BaseA, BaseB {
    using BaseA::BaseA; // Inherits BaseA(int)
    using BaseB::BaseB; // Inherits BaseB(double)
};

Derived d1(10);     // Calls BaseA(10)
Derived d2(5.5);    // Calls BaseB(5.5)
